static inline psl_rval rv_use_count(const nextbuildmanifest_ctx *cx, int32_t cur_nid, psl_rval v) {
  if (cur_nid >= 0 && (size_t)cur_nid < cx->node_count && cx->nodes[cur_nid].decl_sym >= 0) {
    return rv_num((double)cx->syms[cx->nodes[cur_nid].decl_sym].use_count);
  }
  uint32_t sum = 0;
  if (v.kind == RV_STR) {
    for (size_t i = 0; i < cx->sym_count; ++i) {
      if (psl_str_eq(cx->syms[i].name, v.s)) sum += cx->syms[i].use_count;
    }
  }
  return rv_num((double)sum);
}

static inline psl_rval rv_reachable(const nextbuildmanifest_ctx *cx, int32_t cur_nid, psl_rval v) {
  int32_t target = (v.id >= 0) ? v.id : cur_nid;
  if (target < 0 || (size_t)target >= cx->node_count) return rv_bool(1);
  return rv_bool(cx->nodes[target].reachable ? 1 : 0);
}

static inline psl_rval rv_is_immutable(const nextbuildmanifest_ctx *cx, psl_rval v) {
  int32_t sid = sym_lookup(cx, v.s, psl_str_lit("Variable"));
  if (sid < 0) {
    for (size_t i = cx->sym_count; i > 0; --i) {
      if (psl_str_eq(cx->syms[i - 1u].name, v.s)) { sid = (int32_t)(i - 1u); break; }
    }
  }
  if (sid >= 0 && cx->syms[sid].decl_node >= 0) {
    int32_t dnid = cx->syms[sid].decl_node;
    const nextbuildmanifest_node *dn = cx->nodes[dnid].node;
    if (dn && (psl_str_eq(dn->ctor_name, psl_str_lit("ValStmt")) || psl_str_eq(dn->ctor_name, psl_str_lit("PropDecl"))) &&
        dn->child_count > 0 && cx->nodes[cx->nodes[dnid].children[0]].node &&
        cx->nodes[cx->nodes[dnid].children[0]].node->tag == NEXTBUILDMANIFEST_NODE_BOOL) {
      return rv_bool(!cx->nodes[cx->nodes[dnid].children[0]].node->bool_val);
    }
    if (dn && psl_str_eq(dn->ctor_name, psl_str_lit("StmtLet"))) return rv_bool(1);
  }
  return rv_bool(0);
}

static inline psl_rval rv_has_when_else(const nextbuildmanifest_ctx *cx, psl_rval v) {
  for (size_t i = 0; i < v.count; ++i) {
    int32_t cid = v.items[i].id;
    if (cid >= 0 && (size_t)cid < cx->node_count && cx->nodes[cid].node &&
        psl_str_eq(cx->nodes[cid].node->ctor_name, psl_str_lit("WhenElse"))) {
      return rv_bool(1);
    }
  }
  return rv_bool(0);
}

static inline psl_rval rv_df_list(const nextbuildmanifest_ctx *cx, size_t an_idx, int is_after, psl_rval target, int32_t cur_nid) {
  int32_t nid = (target.id >= 0) ? target.id : cur_nid;
  if (nid < 0 || (size_t)nid >= cx->node_count || cx->df_words == 0 || cx->df_univ_count == 0) return rv_empty_list();
  const uint64_t *vec = (is_after ? cx->df_after[an_idx] : cx->df_before[an_idx]) + (size_t)nid * cx->df_words;
  psl_rval *arr = (psl_rval *)psl_arena_alloc(cx->arena, cx->df_univ_count * sizeof(psl_rval), sizeof(void *));
  if (!arr) return rv_empty_list();
  size_t cnt = 0;
  for (size_t u = 0; u < cx->df_univ_count; ++u) {
    if ((vec[u >> 6u] & (UINT64_C(1) << (u & 63u))) != 0u) arr[cnt++] = rv_str(cx->df_univ[u]);
  }
  return rv_list_make(arr, cnt);
}

