static void run_node_passes(nextbuildmanifest_ctx *cx, int32_t nid, int level);

static void exec_node_rule_0(nextbuildmanifest_ctx *cx, int32_t nid, int level, const pat_bind_node_0 *b) {
  (void)cx; (void)nid; (void)level; (void)b;
  int32_t scoped_ids[16];
  size_t scoped_cnt = 0;
  for (size_t ci = 0; ci < cx->nodes[nid].child_count; ++ci) {
    int32_t cid = cx->nodes[nid].children[ci];
    int is_scoped = 0;
    for (size_t si = 0; si < scoped_cnt; ++si) { if (scoped_ids[si] == cid) { is_scoped = 1; break; } }
    if (!is_scoped) run_node_passes(cx, cid, level);
  }
  cx->nodes[nid].type_id = rv_as_type(cx, rv_type(ty_con(cx, psl_str_lit("Scalar"))), level);
}

static void exec_node_rule_1(nextbuildmanifest_ctx *cx, int32_t nid, int level, const pat_bind_node_1 *b) {
  (void)cx; (void)nid; (void)level; (void)b;
  int32_t scoped_ids[16];
  size_t scoped_cnt = 0;
  for (size_t ci = 0; ci < cx->nodes[nid].child_count; ++ci) {
    int32_t cid = cx->nodes[nid].children[ci];
    int is_scoped = 0;
    for (size_t si = 0; si < scoped_cnt; ++si) { if (scoped_ids[si] == cid) { is_scoped = 1; break; } }
    if (!is_scoped) run_node_passes(cx, cid, level);
  }
  cx->nodes[nid].type_id = rv_as_type(cx, rv_type(ty_con(cx, psl_str_lit("Scalar"))), level);
}

