static void run_node_passes(nextbuildmanifest_ctx *cx, int32_t nid, int level) {
  if (level > 128 || nid < 0 || (size_t)nid >= cx->node_count) return;
  if (cx->nodes[nid].scoped_done) return;
  const nextbuildmanifest_node *n = cx->nodes[nid].node;
  if (!n) return;
  {
    pat_bind_node_0 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_0(cx, nid, &b)) {
      exec_node_rule_0(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_1 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_1(cx, nid, &b)) {
      exec_node_rule_1(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_2 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_2(cx, nid, &b)) {
      exec_node_rule_2(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_3 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_3(cx, nid, &b)) {
      exec_node_rule_3(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_4 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_4(cx, nid, &b)) {
      exec_node_rule_4(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_5 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_5(cx, nid, &b)) {
      exec_node_rule_5(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_6 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_6(cx, nid, &b)) {
      exec_node_rule_6(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_7 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_7(cx, nid, &b)) {
      exec_node_rule_7(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_8 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_8(cx, nid, &b)) {
      exec_node_rule_8(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_9 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_9(cx, nid, &b)) {
      exec_node_rule_9(cx, nid, level, &b);
      return;
    }
  }
  {
    pat_bind_node_10 b;
    memset(&b, 0, sizeof(b));
    if (match_pat_node_10(cx, nid, &b)) {
      exec_node_rule_10(cx, nid, level, &b);
      return;
    }
  }
  for (size_t ci = 0; ci < cx->nodes[nid].child_count; ++ci) {
    run_node_passes(cx, cx->nodes[nid].children[ci], level);
  }
}

