static inline size_t df_intern_sym(nextbuildmanifest_ctx *cx, psl_str s, size_t max_u) {
  for (size_t i = 0; i < cx->df_univ_count; ++i) {
    if (psl_str_eq(cx->df_univ[i], s)) return i;
  }
  if (cx->df_univ_count < max_u) {
    cx->df_univ[cx->df_univ_count] = s;
    return cx->df_univ_count++;
  }
  return 0;
}

static void run_dataflow_pass(nextbuildmanifest_ctx *cx) {
  size_t n = cx->node_count;
  if (n == 0) return;
  int32_t *succ_off = (int32_t *)psl_arena_alloc(cx->arena, (n + 1u) * sizeof(int32_t), sizeof(int32_t));
  int32_t *pred_off = (int32_t *)psl_arena_alloc(cx->arena, (n + 1u) * sizeof(int32_t), sizeof(int32_t));
  int32_t *succ_adj = (int32_t *)psl_arena_alloc(cx->arena, (n * 3u + 1u) * sizeof(int32_t), sizeof(int32_t));
  int32_t *pred_adj = (int32_t *)psl_arena_alloc(cx->arena, (n * 3u + 1u) * sizeof(int32_t), sizeof(int32_t));
  uint8_t *kills_seq = (uint8_t *)psl_arena_alloc(cx->arena, n, 1u);
  int32_t *bfs_q = (int32_t *)psl_arena_alloc(cx->arena, n * sizeof(int32_t), sizeof(int32_t));
  if (!succ_off || !pred_off || !succ_adj || !pred_adj || !kills_seq || !bfs_q) return;
  int32_t *eu = (int32_t *)psl_arena_alloc(cx->arena, (n * 2u + 1u) * sizeof(int32_t), sizeof(int32_t));
  int32_t *ev = (int32_t *)psl_arena_alloc(cx->arena, (n * 2u + 1u) * sizeof(int32_t), sizeof(int32_t));
  if (!eu || !ev) return;
  size_t ecnt = 0;
  for (size_t i = 0; i < n; ++i) {
    cx->nodes[i].reachable = 0;
    size_t cc = cx->nodes[i].child_count;
    if (cc > 0 && ecnt < n * 2u) {
      eu[ecnt] = (int32_t)i; ev[ecnt] = cx->nodes[i].children[0]; ++ecnt;
      for (size_t k = 0; k + 1u < cc && ecnt < n * 2u; ++k) {
        int32_t c0 = cx->nodes[i].children[k];
        int32_t c1 = cx->nodes[i].children[k + 1u];
        if (cx->nodes[c0].node && cx->nodes[c0].node->tag == NEXTBUILDMANIFEST_NODE_LIST && cx->nodes[c0].child_count > 0) {
          eu[ecnt] = cx->nodes[c0].children[cx->nodes[c0].child_count - 1u];
        } else {
          eu[ecnt] = c0;
        }
        ev[ecnt] = c1; ++ecnt;
      }
    }
  }
  for (size_t e = 0; e < ecnt; ++e) {
    ++succ_off[eu[e] + 1];
    ++pred_off[ev[e] + 1];
  }
  for (size_t i = 1; i <= n; ++i) { succ_off[i] += succ_off[i - 1u]; pred_off[i] += pred_off[i - 1u]; }
  int32_t *scur = (int32_t *)psl_arena_alloc(cx->arena, n * sizeof(int32_t), sizeof(int32_t));
  int32_t *pcur = (int32_t *)psl_arena_alloc(cx->arena, n * sizeof(int32_t), sizeof(int32_t));
  if (!scur || !pcur) return;
  for (size_t i = 0; i < n; ++i) { scur[i] = succ_off[i]; pcur[i] = pred_off[i]; }
  for (size_t e = 0; e < ecnt; ++e) {
    succ_adj[scur[eu[e]]++] = ev[e];
    pred_adj[pcur[ev[e]]++] = eu[e];
  }
  size_t qh = 0, qt = 0;
  bfs_q[qt++] = 0;
  cx->nodes[0].reachable = 1;
  while (qh < qt) {
    int32_t u = bfs_q[qh++];
    for (int32_t ei = succ_off[u]; ei < succ_off[u + 1]; ++ei) {
      int32_t v = succ_adj[ei];
      if (kills_seq[u] && cx->nodes[u].parent_id == cx->nodes[v].parent_id) continue;
      if (!cx->nodes[v].reachable) { cx->nodes[v].reachable = 1; bfs_q[qt++] = v; }
    }
  }
  cx->cfg_blocks = qt;
}

